def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider between two equally sized panels.
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]) and r % 2 == 1 and r == h // 2:
            n = r
            return [
                [2 if grid[i][j] != 0 and grid[i + n + 1][j] != 0 else 0
                 for j in range(w)]
                for i in range(n)
            ]

    for c in range(w):
        if all(grid[i][c] == grid[0][c] for i in range(h)) and c == w // 2:
            n = c
            return [
                [2 if grid[i][j] != 0 and grid[i][j + n + 1] != 0 else 0
                 for j in range(n)]
                for i in range(h)
            ]

    return grid
